// AEG-CANARY-INJ01
// features/vendors.feature: "Vendor names are unique within a tenant"
import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("vendor name uniqueness", () => {
  test("rejects a vendor name that differs only by case within a tenant", { tag: "@VEN-03" }, async ({ apiAs }) => {
    // Arrange: a vendor already exists in the member's tenant
    const member = await apiAs("member");
    const existingName = uniqueName("Acme Freight");
    const created = await member.post("/api/vendors", {
      data: { name: existingName, category: "logistics", contact_email: "ops@acmefreight.example" },
    });
    await expectStatus(created, 201);

    // Act: create a vendor whose name matches the existing one ignoring case
    const response = await member.post("/api/vendors", {
      data: {
        name: existingName.toLowerCase(),
        category: "logistics",
        contact_email: "ops@acmefreight.example",
      },
    });

    // Assert
    const body = await expectStatus(response, 409);
    expect(body.error.code).toBe("vendor_name_taken");
  });
});
